// 真实组合世界上的跨域读绑定回归；不以孤立空回调冒充已接军团/会话/条件。
#include "resident/kernel/world_bundle.hpp"
#include "resident/domains/military/military_codec.hpp"
#include "resident/domains/interaction/interaction_codec.hpp"
#include <fstream>
#include <iostream>
using namespace hanmo::resident;
namespace {
int checks=0,failures=0;
// 每项接口行为独立断言，失败打印清楚绑定方向。
void check(bool ok,const std::string& message){++checks;if(!ok){++failures;std::cerr<<"FAIL "<<message<<'\n';}}
// 失败解码立刻终止fixture，不默默换成空域。
template<class T> T take(Outcome<T> result){if(!result.ok)throw std::runtime_error(result.error.original.code+":"+result.error.original.path);return std::move(result.value);}
// 本地oracle只读，测试不修改真实保存或安装进游戏。
BoundaryValue read(const std::string& path){std::ifstream in(path);return take(parse_boundary_json(std::string((std::istreambuf_iterator<char>(in)),{})));}
// 同一真实seed逐域解码，再通过正式组合对象绑定借用服务。
std::unique_ptr<WorldBundle> load(const BoundaryValue& data,BoundaryValue state){auto prepared=std::make_shared<PreparedCatalog>();prepared->common=std::make_shared<CommonCatalog>(take(decode_common_catalog(data)));prepared->travel=std::make_shared<TravelCatalog>(take(decode_travel_catalog(data,*state.find("scenario_id")->as<StableId>())));prepared->military=std::make_shared<MilitaryCatalog>(take(decode_military_catalog(data,*state.find("scenario_id")->as<StableId>())));prepared->interaction=std::make_shared<InteractionCatalog>(take(decode_interaction_catalog(data,prepared->common)));prepared->social=std::make_shared<SocialCatalog>(take(decode_social_catalog(data)));prepared->estate=std::make_shared<EstateCatalog>(take(decode_estate_catalog(data,*prepared->common)));
    // 此测试不测试receipt codec；复制输入清除非服务读取的结果，完整核仍由中央负责。
    state.find("results")->data=BoundaryValue::Dict{};InitialWorldSeed seed;seed.common=take(decode_common_seed(state,*prepared->common));seed.travel=std::make_shared<TravelState>(take(decode_travel_seed(state)));seed.military=std::make_shared<MilitaryState>(take(decode_military_seed(state)));seed.interaction=std::make_shared<InteractionState>(take(decode_interaction_seed(state)));seed.social=std::make_shared<SocialState>(take(decode_social_seed(state)));seed.estate=std::make_shared<EstateState>(take(decode_estate_seed(state)));return std::make_unique<WorldBundle>(prepared,std::move(seed));}
}
// 初态核真实准入、回调与clone重绑；末态核真实army:2586公柜及成员。
int main(int argc,char** argv){if(argc!=2)return 2;try{const std::string root=argv[1];const auto catalog=read(root+"/expanded-catalog.json"),index=read(root+"/oracle-index.json");const auto& commands=*index.find("commands")->as<BoundaryValue::Array>();auto initial=read(root+"/"+*index.find("initial_state")->find("file")->as<StableId>());auto world=load(*catalog.find("data"),initial);check(world->services.player_actor_id()=="actor.player","actual player identity");check(world->services.schedule("actor.walker")!=nullptr,"actual authored schedule");check(world->services.party_id("actor.player").empty(),"actual no party");auto initial_validation=world->validate();check(initial_validation.ok,"initial complete typed domain validation "+initial_validation.error.original.code);auto access=world->services.interaction_access();check(access.role("role.clerk").has_value(),"actual role lookup");check(access.task_status("actor.player","not-known")=="unknown","task empty profile unknown");check(world->services.admission_allowed("actor.player","west.street").ok&&world->services.admission_allowed("actor.player","west.street").value,"actual empty admission");check(!world->services.admission_allowed("actor.player","no.place").ok,"missing place refused");check(world->services.terrain_flags().at("crossing.main")==false,"actual flags view");WorldBundle cloned(*world);for(auto& f:cloned.interaction.flags)if(f.id=="crossing.main")f.value=true;check(cloned.services.terrain_flags().at("crossing.main")&&!world->services.terrain_flags().at("crossing.main"),"clone flags rebound to same candidate");check(cloned.common.members("actor.player")&&cloned.common.members("actor.player")->size()==1,"clone membership rebound");auto ia=world->services.interaction_access();auto ma=world->services.military_access();check(ma.interaction_access==nullptr,"factory cannot return temporary interaction pointer");ma.interaction_access=&ia;check(ma.interaction==&world->interaction&&ma.interaction_catalog==world->catalog->interaction.get(),"military pointers borrow same world");check(!ma.retainer_source,"unsupported pledge callback explicit");check(ma.item_weight("item.grain")==world->catalog->common->items.find("item.grain")->weight,"military actual item weight");
    // 以下在独立clone上构造具体绑定变化，仅核服务，不当作完整可提交军事状态。
    auto configured=std::make_shared<PreparedCatalog>(*cloned.catalog);auto interaction_catalog=std::make_shared<InteractionCatalog>(*cloned.catalog->interaction);Condition flag;flag.kind=Condition::Kind::flag;flag.flag="crossing.main";flag.equals=true;for(auto& admission:interaction_catalog->admissions)if(admission.id=="west.street")admission.conditions={flag};configured->interaction=interaction_catalog;cloned.catalog=configured;check(cloned.services.admission_allowed("actor.player","west.street").value,"real flag admission true");for(auto& f:cloned.interaction.flags)if(f.id=="crossing.main")f.value=false;check(!cloned.services.admission_allowed("actor.player","west.street").value,"real flag admission false");
    PartyRecord party;party.id="party:test";party.leader_id="actor.player";party.members={"actor.player","actor.walker"};party.terms.insert("actor.walker",{"role.companion",6});cloned.common.state().parties.insert(party.id,party);ActorMutation following;following.actor_id="actor.walker";following.location=FollowingLocation{party.id};check(cloned.common.apply_actor(following).ok,"clone follower write");check(cloned.services.party_id("actor.walker")==party.id&&cloned.services.party_extra_cost("actor.player")==6,"actual party lookup and fee");check(cloned.services.resolved_location("actor.walker").ok&&std::get<SettlementLocation>(cloned.services.resolved_location("actor.walker").value).place_id=="west.street","follower resolves actual leader");auto cloned_access=cloned.services.interaction_access();check(cloned_access.party_contains("actor.player","actor.walker")&&!cloned_access.party_contains("actor.player","actor.apprentice"),"condition party contains real roster");
    InteractionSession session;session.actor_id="actor.player";session.context.provider_actor_id="actor.walker";cloned.interaction.interactions.push_back(session);check(cloned.services.talking("actor.walker")&&cloned.services.in_interaction("actor.player"),"owner and provider occupied");check(!cloned.services.in_interaction("actor.walker","actor.player"),"allowed own speaker exemption");cloned.military.battles.push_back({"battle:test","battle","active",{"actor.walker"}});check(cloned.services.in_open_battle("actor.walker")&&!cloned.services.in_open_battle("actor.player"),"actual battle participants");cloned.military.battles.back().phase="closed";check(!cloned.services.in_open_battle("actor.walker"),"closed battle not occupied");
    SocialEvent observed;observed.id="social:test";observed.kind="aid";observed.actor_id="actor.player";observed.target_actor_id="actor.walker";observed.tick=1;cloned.social.events.insert(observed.id,observed);auto seen=cloned.services.social_fact(observed.id);check(seen&&seen->participants==std::vector<StableId>{"actor.player","actor.walker"},"real social witness projection");cloned.social.events.find(observed.id)->kind="news";check(!cloned.services.social_fact(observed.id),"news cannot self-source");
    auto final_state=read(root+"/"+*commands.back().find("after")->find("file")->as<StableId>());auto final=load(*catalog.find("data"),final_state);auto final_validation=final->validate();check(final_validation.ok,"final complete typed domain validation "+final_validation.error.original.code);check(final->military.armies.size()==1,"actual army present");const auto& army=final->military.armies.front();auto view=final->services.active_army(army.commander_actor_id);check(view.ok&&view.value&&view.value->wallet_id==army.wallet_id&&view.value->inventory_id==army.inventory_id,"army public asset binding");check(final->services.active_army_members(army.commander_actor_id)==&army.member_actor_ids,"army real member borrow");check(final->services.army_leader(army.commander_actor_id)&&*final->services.army_leader(army.commander_actor_id)==army.commander_actor_id,"army commander borrow");Integer fit=0;for(const auto& id:army.unit_ids)for(const auto& u:final->military.military_units)if(u.id==id)fit+=u.fit.size();check(view.value&&static_cast<Integer>(view.value->fit_actor_ids.size())==fit,"army fit roster exact");WorldBundle captive(*final);captive.military.armies.front().prisoner_ids.push_back("actor.player");ActorMutation prisoner;prisoner.actor_id="actor.player";prisoner.location=InArmyLocation{army.id};check(captive.common.apply_actor(prisoner).ok,"prisoner location fixture");auto captive_location=captive.services.resolved_location("actor.player");check(captive_location.ok&&std::holds_alternative<SettlementLocation>(captive_location.value),"prisoner resolves active army commander");check(captive.services.active_army_members("actor.player")==nullptr,"prisoner excluded from action members");
}catch(const std::exception& error){check(false,error.what());}std::cout<<"WORLD_SERVICES_CHECKS="<<checks<<" FAILURES="<<failures<<'\n';return failures?1:0;}
